import os
import torch


class Config:
    """
    Configuration class for the Chatbot Arena Preference Prediction pipeline.
    Defines file paths, model hyperparameters, and training settings.
    """

    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # File Paths & Directories
    # ==========================================
    # Input Metadata (Generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory for Cache (Embeddings, Models)
    WORKING_DIR = "./working/idea_1"
    CACHE_DIR = WORKING_DIR

    # Output Directory for Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model Checkpoint Path
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # ==========================================
    # Model Architecture
    # ==========================================
    # Backbone: Lightweight Sentence Transformer
    TRANSFORMER_MODEL = "sentence-transformers/all-MiniLM-L6-v2"

    # Text Processing
    MAX_LENGTH = 256  # Max token length for the transformer
    EMBEDDING_DIM = 384  # Output dimension of all-MiniLM-L6-v2

    # MLP Head Configuration
    # Input dim will be EMBEDDING_DIM * 4 (Prompt, ResA, ResB, Diff, Prod -> Wait, idea says:
    # 1. Prompt, 2. ResA, 3. ResB.
    # Plus interaction: Diff (A-B) and Prod (A*B).
    # Total vectors: Prompt(1) + ResA(1) + ResB(1) + Diff(1) + Prod(1) = 5 vectors?
    # Or Prompt, ResA, ResB, Diff, Prod.
    # Let's assume the feature builder will concatenate these.
    # 5 * 384 = 1920 input features.
    HIDDEN_LAYERS = [1024, 512, 256]
    DROPOUT_RATE = 0.3
    NUM_CLASSES = 3  # Winner A, Winner B, Tie

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 256
    LEARNING_RATE = 1e-3
    EPOCHS = 50
    EARLY_STOPPING_PATIENCE = 5

    # ==========================================
    # Runtime & Debugging
    # ==========================================
    # Set DEBUG to True to run on a small subset of data for testing
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 2000

    # Hardware settings
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    @classmethod
    def setup(cls):
        """Creates necessary output directories if they don't exist."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Initialize directories upon module import
Config.setup()
